cd /workspace && python3 - <<'PYEOF'
import json, random, subprocess, sys, time
rng = random.Random(5)
topology = {
    "nodes": [{"id": i, "name": "N%d" % i, "external_capacity": 1000} for i in range(256)],
    "links": [{"source": i, "target": (i + 1) % 256, "capacity": 1000} for i in range(256)],
    "external_nodes": ["N%d" % i for i in range(16)]}
names = {n["id"]: n["name"] for n in topology["nodes"]}
blob = "x" * 4000
counters = {}
for link in topology["links"]:
    a, b = link["source"], link["target"]
    counters["low_%s_egress_to_%s" % (names[a], names[b])] = {"perturbed": 500, "ground_truth": blob}
    counters["low_%s_ingress_from_%s" % (names[b], names[a])] = {"perturbed": 500, "corrected": blob}
for e in range(16):
    counters["low_%s_origination" % names[e]] = {"perturbed": 500, "confidence": blob}
    counters["low_%s_termination" % names[e]] = {"perturbed": 500, "confidence": blob}
plan = {}
for i, a in enumerate(range(16)):
    for b in range(i + 1, 16):
        plan.setdefault(names[a], {})[names[b]] = [{"path": [names[a], names[b]], "weight": 1000}]
        plan.setdefault(names[b], {})[names[a]] = [{"path": [names[b], names[a]], "weight": 1000}]
settings = {"trials": 32, "epsilon": 250000, "seed": 42, "cutoff": [0, 1], "bias": 0,
             "tau": 1000, "gamma": [1, 2], "cache_slots": 8}
streams = [{"topology": topology, "settings": settings, "events": [
    {"op": "patch", "demands": [[a, b, 100] for a in range(16) for b in range(16) if a != b],
     "counters": counters},
    {"op": "routes", "label": "p", "paths": plan},
    {"op": "repair", "id": "r"}, {"op": "validate", "id": "r"}]} for _ in range(4)]
data = json.dumps({"streams": streams}).encode()
print("request bytes:", len(data), "(limit 8 MiB =", 8 * 1024 * 1024, ")")
start = time.monotonic()
proc = subprocess.run([sys.executable, '-B', '-u', '/workspace/submission/main.py'], input=data,
                      capture_output=True, timeout=600)
print("elapsed %.2fs rc=%d" % (time.monotonic() - start, proc.returncode))
if proc.returncode:
    print(proc.stderr.decode()[:2000])
else:
    out = json.loads(proc.stdout.decode())
    print("streams:", len(out["streams"]), "answers:", [len(s["events"]) for s in out["streams"]])
    print("repair ok:", out["streams"][0]["events"][2]["cache_hit"], len(out["streams"][0]["events"][2]["links"]))
PYEOF
